// Skip clustering: pass articles through with default General cluster
const articles = $('Input').all().map(i => i.json);
console.log('Clustering SKIPPED: ' + articles.length + ' articles passed through with cluster=General');
return articles.map(a => ({ json: { ...a, cluster: 0, cluster_label: 'General' } }));

// === CLUSTERING v2 - Formule amelioree + abstracts ===
// PROMPT_SANS_EXEMPLE_v1 (2026-10-19, lot 0 de la 0.5.3). CE QUI ETAIT FAUX : le prompt donnait
// deux etiquettes d'exemple (un sujet de prevalence, des facteurs de risque) et une forme a valeurs
// (un nom de theme et une liste d'indices ecrits). Un petit modele recopie ce qu'on lui montre :
// le tri a deja rendu, mot pour mot, la justification de son exemple pour chaque article (fiche
// « few-shot recopie »). Au run reel du 2026-09-21 (402 articles), 20 etiquettes sur 50 reprennent
// les mots des deux exemples ; c'est un indice, pas une preuve, ces themes existant dans le corpus.
// CE QUI CHANGE : la forme attendue est DECRITE clef par clef, sans aucune valeur a recopier, et la
// regle du nom dit ce qu'il doit nommer. tests/test_regroupement_fusion_dite.py execute ce nœud et
// lit ses prompts.
const items = $input.all();
const articles = items.map(i => i.json);

if (articles.length < 3) {
  console.log('Clustering: < 3 articles, assigning General');
  return articles.map(a => ({ json: { ...a, cluster: 0, cluster_label: 'General' } }));
}

const BATCH_SIZE = 25;
// Formule amelioree: sqrt(n), plafond a 6, plancher a 2
// Evite la sur-segmentation tout en restant adaptatif
// NOMBRE DE THEMES VISE. Le plafond etait de SIX, applique aussi bien a 110 articles qu'a
// 3 000 : un corpus dix fois plus gros recevait la meme consigne. L'echelle est desormais
// logarithmique, ce qui suit la croissance reelle du nombre de thèmes distincts dans un
// corpus, et le plafond passe a douze (au-dela, une carte thematique devient illisible).
const targetClusters = Math.min(12, Math.max(2,
  Math.round(2 * Math.log2(articles.length / 10 + 2))));
// TAILLE MINIMALE PAR THEME, RAMENEE A L'ECHELLE DU LOT. Elle etait calculee sur le corpus
// ENTIER puis annoncee a un prompt qui ne porte que BATCH_SIZE articles : pour 500 articles,
// « au moins 41 par thème » dans un lot de 25. Arithmetiquement impossible des ~300
// articles, donc traitee comme du bruit par le modele. On raisonne desormais PAR LOT.
const parLot = Math.min(BATCH_SIZE, articles.length);
const ciblesParLot = Math.max(2, Math.min(targetClusters, Math.round(parLot / 6)));
const minPerCluster = Math.max(2, Math.floor(parLot / (ciblesParLot * 1.5)));
// CADENCE_v1 : intervalle d'emission des appels au modele, calcule par le moteur
// (src/cadence.py) et pose sur chaque lot, car le nœud suivant le lit sur les elements
// qu'il recoit. Sans lui, le nœud emet a intervalle fixe sans attendre les reponses et la
// file d'attente enfle sans limite : c'est ce qui a fait perdre un tri de 12 772
// references le 2026-08-07 (6 422 fils, moteur injoignable, execution tuee).
// UNE CADENCE ABSENTE N'EST PAS UN ZERO MESURE (2026-10-20, P05 de l'inventaire des defauts
// restants, verification du tour 1 du lot). Ce qui etait faux : l'absence donnait 0, et le repli
// prudent du nœud d'appel (1 800 ms) n'etait jamais atteint. MESURE (vrai routeur, vrai nœud, corps
// de lancement sans `pacing_ms`) : chaque appel au modele partait a 0 ms. Ce qui change : absente
// ou illisible, la cadence vaut null et le nœud d'appel prend son repli ; une cadence recue, zero
// compris, passe bornee a zero, comme avant.
const __cadence = parseInt((articles[0] || {})._pacing_ms, 10);
const _pacing = Number.isFinite(__cadence) ? Math.max(0, __cadence) : null;
const batches = [];

for (let i = 0; i < articles.length; i += BATCH_SIZE) {
  const batch = articles.slice(i, i + BATCH_SIZE);
  const articleList = batch.map((a, j) => {
    const title = (a.title || 'No title').substring(0, 120);
    const abstract = (a.abstract || '').substring(0, 200);
    return j + ': ' + title + (abstract ? ' -- ' + abstract : '');
  }).join('\n');

  const prompt = `You are a scientific literature analyst specializing in thematic grouping. Organize these articles into coherent thematic clusters based on their content. Return ONLY valid JSON.\n\nArticles (index: title -- abstract excerpt):\n${articleList}\n\nANSWER FORMAT: one JSON object with a single key "clusters". Its value is a list with one object per cluster, and each object has exactly three keys: "id" (an integer, counting from 0), "label" (the name of the cluster) and "articles" (the list of the indices of the articles placed in the cluster).\n\nRULES:\n1. Create between 2 and ${ciblesParLot} clusters maximum.\n2. Each cluster MUST contain at least ${minPerCluster} articles. Do NOT create clusters with only 1 article.\n3. Each label is a short noun phrase of 3 to 8 words, written for THESE articles: it names what the articles of the cluster share (topic, population, exposure or method). Never a generic name (a number, a letter or a catch-all word).\n4. Every article index from 0 to ${batch.length - 1} must appear in exactly one cluster.\n5. Group articles by shared research themes, methodologies, or populations studied.\n6. Prefer fewer, broader clusters over many small ones. When in doubt, merge.`;

  batches.push({ json: { _pacing_ms: _pacing, prompt, batchIndex: Math.floor(i / BATCH_SIZE), batchSize: batch.length, targetClusters, ciblesParLot, minPerCluster } });
}

console.log('Clustering v2: ' + articles.length + ' articles -> ' + batches.length + ' batches, target ' + targetClusters + ' clusters (min ' + minPerCluster + '/cluster)');
return batches;

// === EXPAND v2 - Assign + consolidation intelligente ===
const responses = $input.all();
const originalItems = $('Input').all();
const articles = originalItems.map(i => i.json);
const BATCH_SIZE = 25;
// LU AU BON ENDROIT. `responses` sont les reponses HTTP du modele : elles ne portent pas
// `targetClusters`, donc cette valeur valait TOUJOURS 4, quelle que soit la taille du
// corpus, et le seuil de declenchement de la consolidation etait constant. Le nombre vise
// est calcule par « Prepare Batches » : c'est la qu'il faut le prendre.
// AVANCEMENT. Le module declarait son total au demarrage et ne tickait JAMAIS : sur un gros
// corpus, la barre restait a zero pendant toute sa duree et l'utilisateur croyait a un
// plantage. Le clustering n'appelle le modele qu'une fois par LOT, pas par article : on
// publie donc l'avancement en articles traites, ce que la barre attend.
try {
  const faits = responses.length * BATCH_SIZE;
  await this.helpers.httpRequest({ method: 'POST',
    url: 'http://host.docker.internal:8080/api/module-progress/tick',
    body: JSON.stringify({ mode: 'clustering', current: faits, total: originalItems.length }),
    headers: { 'Content-Type': 'application/json' }, timeout: 5000 });
} catch (e) { /* un compteur ne doit jamais faire echouer un run */ }
let targetClusters = 4;
try {
  const prep = $('Prepare Batches').all();
  const v = prep && prep[0] && prep[0].json && prep[0].json.targetClusters;
  if (typeof v === 'number' && v > 0) targetClusters = v;
} catch (e) { console.log('[clustering] nombre vise indisponible : ' + e.message); }

// MOINS DE TROIS ARTICLES (2026-10-19, lot 0 de la 0.5.3). « Prepare Batches » les range dans
// « General » sans faire de lot (meme seuil de trois), mais le nœud d'appel les recoit quand
// meme : chacun part sans invite, le serveur de modeles rend une reponse vide, et ce nœud les
// declarait « Unclustered », donc « Non classes (lot en echec) » au rapport et a l'ecran, alors
// qu'aucun lot n'avait echoue. MESURE (tests/test_regroupement_fusion_dite.py) : 2 articles,
// sortie Unclustered et Unclustered. Ils restent dans « General ».
// Statut « sans_lot » (second tour du 2026-10-19) : « non_requise », pose ici d'abord, faisait
// ecrire au rapport « les lots ont rendu 1 theme(s), pas plus que le nombre vise » alors qu'il n'y
// a ni lot ni nombre vise. Aucune etiquette n'est ecrite par un lot : etiquettes_avant vaut 0.
if (articles.length < 3) {
  const _seul = { statut: 'sans_lot', etiquettes_avant: 0, themes_apres: 1, themes_vises: null,
    rattachees: 0 };
  return articles.map(a => ({ json: { ...a, cluster: 0, cluster_label: 'General', _fusion_themes: _seul } }));
}

const allLabels = new Array(articles.length).fill('Unclustered');
const batchLabels = [];

for (let r = 0; r < responses.length; r++) {
  const resp = responses[r].json;
  try {
    const responseText = resp.response || '';
    const inner = JSON.parse(responseText);
    (inner.clusters || []).forEach(cluster => {
      const label = cluster.label || ('Cluster ' + cluster.id);
      if (!batchLabels.includes(label)) batchLabels.push(label);
      (cluster.articles || []).forEach(idx => {
        const globalIdx = r * BATCH_SIZE + idx;
        if (globalIdx >= 0 && globalIdx < articles.length) {
          allLabels[globalIdx] = label;
        }
      });
    });
  } catch(e) {
    console.log('Clustering parse error batch ' + r + ': ' + e.message);
  }
}

const labelToId = {};
let nextId = 0;

const results = articles.map((article, i) => {
  const label = allLabels[i];
  if (!(label in labelToId)) labelToId[label] = nextId++;
  return { json: { ...article, cluster: labelToId[label], cluster_label: label } };
});

const uniqueLabels = [...new Set(allLabels.filter(l => l !== 'Unclustered'))];
console.log('Clustering: ' + articles.length + ' articles in ' + uniqueLabels.length + ' clusters');

// FUSION_DITE_v1 (2026-10-19, lot 0 de la 0.5.3). LA FUSION DIT CE QU'ELLE A FAIT, MEME QUAND
// ELLE N'A PAS LIEU. Chaque article porte `_fusion_themes` (statut nomme et comptes), que
// « Assemble Results » publie dans les statistiques et ecrit au rapport. Statuts poses ici :
//   - « echec_arret » : le run a ete arrete pendant les lots. Le relais rend alors une reponse
//     vide marquee `ultralab_cancelled` (src/proxy.py) aux lots restants, et il refuserait aussi
//     l'appel de fusion : il n'est pas fait, les etiquettes deja ecrites sont gardees. Second tour
//     du 2026-10-19 : un tel run qui rendait au plus le nombre vise d'etiquettes etait dit
//     « non_requise » (« pas ete necessaire », 0 theme quand tous les lots etaient refuses) ;
//   - « sans_etiquette » : aucun lot n'a rendu d'etiquette, il n'y a rien a fusionner (second
//     tour : c'etait aussi « non_requise ») ;
//   - « non_requise » : les lots rendent au plus le nombre de themes vise ;
//   - « non_tentee » : plus de MAX_ETIQUETTES_FUSION etiquettes. La fusion se fait en UN appel, qui
//     lit toutes les etiquettes. 500 est une LIMITE FIXEE avec de la marge, et non la limite de
//     lecture du modele. MESURE du 2026-10-19, nœud « Build Consolidation Prompt » execute, 12
//     themes vises : 500 etiquettes de 100 caracteres demandent 25 423 jetons, marge comprise, sur
//     les 32 768 du dernier palier, et un appel en tiendrait 651 (787 de 75 caracteres, la longueur
//     du run reel). Au-dela de la limite, la fusion n'est pas tentee, les etiquettes des lots sont
//     gardees, et le resultat le dit. Une fusion en plusieurs tours reste a faire. (Second tour :
//     ce commentaire et les textes montres disaient qu'un appel « ne pourrait pas tout lire », ce
//     que cette mesure contredit.)
// L'estimation de duree du module suit cette limite (src/server.py, MAX_ETIQUETTES_FUSION) : le
// cas test_le_plafond_EXECUTE_par_le_noeud_est_celui_du_moteur execute ce nœud aux deux bords.
const MAX_ETIQUETTES_FUSION = 500;
const _arrete = responses.some(r => r && r.json && r.json.ultralab_cancelled);
if (!_arrete && uniqueLabels.length > targetClusters && uniqueLabels.length <= MAX_ETIQUETTES_FUSION) {
  console.log('Consolidation necessaire: ' + uniqueLabels.length + ' -> ' + targetClusters + ' clusters');
  return [{ json: {
    _needsConsolidation: true,
    _consolidateLabels: uniqueLabels,
    _targetClusters: targetClusters,
    _articles: results.map(r => r.json)
  }}];
}
let statut;
if (_arrete) {
  statut = 'echec_arret';
  console.log('Fusion des etiquettes NON FAITE : run arrete pendant les lots ; '
    + uniqueLabels.length + ' etiquettes deja ecrites, gardees telles quelles');
} else if (uniqueLabels.length === 0) {
  statut = 'sans_etiquette';
  console.log('Fusion des etiquettes NON FAITE : aucun lot n\'a rendu d\'etiquette');
} else if (uniqueLabels.length > targetClusters) {
  statut = 'non_tentee';
  console.log('Fusion des etiquettes NON TENTEE : ' + uniqueLabels.length + ' etiquettes, plus que la '
    + 'limite fixee de ' + MAX_ETIQUETTES_FUSION + ' ; elles sont gardees telles quelles');
} else {
  statut = 'non_requise';
}
const _fusion = { statut: statut, etiquettes_avant: uniqueLabels.length,
  themes_apres: uniqueLabels.length, themes_vises: targetClusters, rattachees: 0 };
return results.map(r => ({ json: { ...r.json, _fusion_themes: _fusion } }));

// === FUSION DES ETIQUETTES : prompt par INDICES, budget proportionne (FUSION_DITE_v1) ===
// 2026-10-19, lot 0 de la 0.5.3. CE QUI ETAIT FAUX : la fusion demandait une table qui RECOPIE
// chaque etiquette d'origine et sa nouvelle etiquette, avec au plus 800 jetons de reponse quel que
// soit le nombre d'etiquettes (nœud « Call Ollama Consolidate »). MESURE
// (tests/test_regroupement_fusion_dite.py) : pour 50 etiquettes de la longueur de celles du run
// reel (402 articles, 11 themes vises), la reponse complete de cette forme tient environ 2 500
// jetons a 3 caracteres par jeton ; coupee a 800, elle ne se lit pas, et les 50 etiquettes
// sortaient telles quelles sans que rien ne le dise.
// CE QUI CHANGE.
//   - Le modele rend des INDICES (« themes » : un nom et les numeros des etiquettes regroupees) :
//     la reponse raccourcit, et plus rien ne depend d'une recopie exacte des etiquettes.
//   - La forme est DECRITE clef par clef, sans aucune valeur a recopier (fiche « few-shot
//     recopie » : un petit modele rend l'exemple au lieu de repondre).
//   - Le budget de reponse suit le nombre d'etiquettes et le nombre vise ; le contexte suit
//     l'invite et la reponse, par paliers (un contexte qui change d'un appel a l'autre recharge le
//     modele : 50 etiquettes restent au palier des lots, 8 192).
//   - La limite MAX_ETIQUETTES_FUSION (nœud « Expand Results ») garantit que le dernier palier
//     suffit : 500 etiquettes de 100 caracteres demandent 25 423 jetons sur 32 768. C'est une
//     limite FIXEE avec de la marge (par ce calcul, un appel en tiendrait 651), et non la limite
//     de lecture du modele (second tour du 2026-10-19 : les textes montres pretendaient le
//     contraire).
const data = $input.all()[0].json;
const labels = data._consolidateLabels || [];
const tc = data._targetClusters || 4;
const articles = data._articles || [];

// Compter les articles par label pour aider le LLM
const labelCounts = {};
for (const a of articles) {
  const l = a.cluster_label || 'Unclustered';
  labelCounts[l] = (labelCounts[l] || 0) + 1;
}

// Une etiquette est montree sur 100 caracteres au plus, guillemets doubles remplaces : le modele
// rend des indices, le texte ne sert qu'a comprendre le theme.
const montree = (l) => {
  const t = String(l).replace(/"/g, "'");
  return t.length > 100 ? t.substring(0, 97) + '...' : t;
};
const labelList = labels.map((l, i) => i + ': "' + montree(l) + '" (' + (labelCounts[l] || 0) + ' articles)').join('\n');

const prompt = `You are a scientific literature analyst. These ${labels.length} theme labels were written batch by batch for one corpus of articles, so several of them name the same theme in different words. Merge them into exactly ${tc} broader themes. Return ONLY valid JSON.\n\nLabels (index: "label" (number of articles)):\n${labelList}\n\nANSWER FORMAT: one JSON object with a single key "themes". Its value is a list with one object per merged theme, and each object has exactly two keys: "label" (the name of the merged theme) and "members" (the list of the indices of the labels merged into it).\n\nRULES:\n1. Create exactly ${tc} merged themes.\n2. Every index from 0 to ${labels.length - 1} must appear in exactly one "members" list.\n3. Merge labels that name the same or overlapping themes, and merge small themes into the closest larger one.\n4. Each merged label is a short noun phrase of 3 to 8 words naming what its members share. Never a generic name (a number, a letter or a catch-all word).\n5. Write only indices in "members", never the labels themselves.`;

// BUDGET DE REPONSE. Un theme fusionne coute une trentaine de jetons au plus (un nom de 3 a 8 mots
// et la structure), un indice quatre au plus (certains modeles comptent les chiffres un a un, plus
// la virgule) : le budget en accorde 48 et 8, plus 128 de marge. Mesure du cas des 50 etiquettes :
// 1 056 jetons accordes, reponse complete d'environ 340 jetons a 3 caracteres par jeton (510 a 2) ;
// au plafond de 500 etiquettes, 4 704 accordes pour environ 1 100 (1 650 a 2).
const numPredict = 128 + 48 * tc + 8 * labels.length;
// CONTEXTE. L'invite est comptee a 3 caracteres par jeton (une etiquette anglaise en fait pres de
// 4) ; le contexte est le premier palier qui tient l'invite, la reponse et 256 jetons de marge. Le
// dernier palier sert de repli : la limite d'etiquettes fait qu'il suffit toujours.
const PALIERS = [8192, 16384, 32768];
const besoin = Math.ceil(prompt.length / 3) + numPredict + 256;
const numCtx = PALIERS.find((p) => p >= besoin) || PALIERS[PALIERS.length - 1];

console.log('Fusion des etiquettes : ' + labels.length + ' etiquettes vers ' + tc + ' themes, '
  + numPredict + ' jetons de reponse, contexte ' + numCtx);
return [{ json: { prompt, _articles: articles, _targetClusters: tc, _labels: labels,
  _num_predict: numPredict, _num_ctx: numCtx } }];

// === APPLY LABELS : la fusion appliquee, et DITE (FUSION_DITE_v1) ===
// 2026-10-19, lot 0 de la 0.5.3. CE QUI ETAIT FAUX : une reponse illisible (coupee par la limite
// de longueur, vide, hors de la forme demandee) laissait la table de fusion vide, et toutes les
// etiquettes des lots etaient gardees SANS LE DIRE, ni au resultat ni a l'ecran. Le journal
// comptait les clefs de la table comme « labels fusionnes », meme quand aucune ne correspondait a
// une etiquette. Au run reel du 2026-09-21 : 50 themes pour 11 vises.
// CE QUI CHANGE : chaque article porte `_fusion_themes`, le statut NOMME de la fusion et ses
// comptes ; « Assemble Results » (workflows/ultralab-module.json) le publie et l'ecrit au rapport,
// l'ecran le rend. Les statuts poses ici :
//   - « echec_arret » : le run a ete arrete avant la fusion ; le relais rend alors une reponse
//     vide marquee `ultralab_cancelled` (src/proxy.py), qui n'est pas une reponse du modele ;
//   - « echec_appel » : l'appel au modele n'a rendu aucune reponse (erreur du nœud d'appel) ;
//   - « echec_coupee » : la reponse ne se lit pas et le modele s'est arrete sur la limite de
//     longueur ;
//   - « echec_illisible » : la reponse ne se lit pas, ou n'a pas la forme demandee ;
//   - « echec_vide » : la reponse se lit mais ne rattache aucune etiquette a un theme nomme ;
//   - « sans_effet » : chaque etiquette reste seule dans son theme, rien n'est regroupe ;
//   - « partielle » : une partie des etiquettes est rattachee, le reste est garde tel quel ;
//   - « faite » : chaque etiquette est rattachee a un theme, et le nombre de themes baisse. Une
//     etiquette peut rester seule dans son theme : elle est RATTACHEE, pas « regroupee » (second
//     tour du 2026-10-19 : les textes montres disaient « regroupee »).
// Un echec ou une reponse sans effet garde les etiquettes des lots, celles que le modele a ecrites
// en lisant les articles. tests/test_regroupement_fusion_dite.py execute ce nœud.
const ollamaResp = (($input.all()[0] || {}).json) || {};
const prevData = $('Build Consolidation Prompt').first().json;
const articles = prevData._articles || [];
const labels = prevData._labels || [];
const tc = prevData._targetClusters || 4;

let statut = null;
// etiquette d'origine -> theme fusionne. Des Map et non des objets : une etiquette nommee comme
// une propriete d'objet (« constructor ») ne doit rien trouver qu'elle n'a pas pose.
const nouvelle = new Map();
if (ollamaResp.ultralab_cancelled) {
  statut = 'echec_arret';
} else if (ollamaResp.error || typeof ollamaResp.response !== 'string') {
  statut = 'echec_appel';
} else {
  let rendu = null;
  try { rendu = JSON.parse(ollamaResp.response); } catch (e) { rendu = null; }
  const themes = (rendu && Array.isArray(rendu.themes)) ? rendu.themes : null;
  if (!themes) {
    statut = ollamaResp.done_reason === 'length' ? 'echec_coupee' : 'echec_illisible';
  } else {
    const parTexte = new Map();
    labels.forEach((l, i) => { if (!parTexte.has(l)) parTexte.set(l, i); });
    // UN NOM QUI NE NOMME RIEN N'EST PAS UN NOM (second tour du 2026-10-19). Le prompt l'interdit
    // (« a number, a letter or a catch-all word »), mais la reponse
    // {"themes": [{"label": 1, ...}, {"label": 2, ...}]} etait acceptee et la fusion dite faite,
    // avec des themes « 1 » et « 2 » (verification du lot). Refuses : un nom de moins de deux
    // lettres (« 1 », « 12 », « A », « #3 ») ; un mot fourre-tout seul ou numerote, dans les formes que
    // la regle enumere (regle exacte et sa limite : voir FOURRE_TOUT, plus bas) (« Cluster 3 »,
    // « Theme 2 », « Other », « Unclustered », qui designe les articles d'un lot en echec). Les
    // etiquettes d'un theme refuse ne sont pas rattachees : elles restent telles que les lots les
    // ont ecrites, et le statut le dit. Toute ecriture compte comme lettres (\p{L}).
    const LETTRE = new RegExp('\\p{L}', 'gu');
    // P24 (2026-10-20) : LA REGLE TIENT CE QUE CE COMMENTAIRE ANNONCE. CE QUI ETAIT FAUX : apres le mot,
    // seuls un s, des espaces, UN caractere parmi # : . et des chiffres etaient admis ; « Cluster-3 »,
    // « Cluster_3 », « Cluster (3) », « Theme A », et « Uncategorized », « Unknown », « N/A » etaient
    // acceptes comme noms (cas : tests/test_regroupement_restes_lot0.py). Sont refuses desormais : un mot
    // de la liste (anglais et francais, dont les mots « sans categorie » et « inconnu »), suivi au plus
    // d'un separateur (# : . _ / ( tiret), d'un numero ou d'une lettre seule, d'une parenthese fermante.
    // Un nom qui continue apres (« Group therapy », « Unknown risk factors ») reste un nom.
    // P24, TOUR 2 (2026-10-20, verification du tour 1) : DES NUMEROTATIONS RESTAIENT ACCEPTEES. Ce qui
    // etait faux : « Theme II », « Category IV » (chiffres romains), « Cluster n°3 », « Cluster No. 3 »,
    // « Topic One », « Cluster three », « Cluster 1/2 », et un effectif ajoute au mot (« Others (n=5) »,
    // « Other (5 studies) », « Theme 1 (n = 12) ») etaient acceptes comme noms : MESURE sur la chaine
    // reelle (cas tests/test_regroupement_restes_lot0.py), fusion dite faite avec ce seul theme.
    // LA REGLE EXACTE, desormais : est refuse un nom fait, dans cet ordre, de
    //   - au plus un rang ecrit devant le mot (FT_RANG : « First », « 2nd », « Deuxieme ») ;
    //   - un mot de FT_MOT (anglais et francais, pluriel admis), ou deux relies par / & , + ou par
    //     and, or, et, ou (« Other / unclassified », « Misc and other ») ;
    //   - au plus un nom generique (FT_GENERIQUE : « studies », « articles », « topics », « etudes ») ;
    //   - au plus un separateur (# : . _ / ( tirets) et un numero (FT_NUMERO : chiffres, lettre seule,
    //     chiffres romains jusqu'a XXXIX, nombre ecrit en lettres jusqu'a 59 en anglais et en francais,
    //     « n° 3 », « No. 3 », « nr 3 », « number 3 », « numero 3 », plage ou fraction « 1/2 », « 1-2 »,
    //     « 3 of 11 ») ;
    //   - au plus une parenthese fermante, un effectif (FT_EFFECTIF : « (n=5) », « (5 studies) »,
    //     « [n = 7] », « : 5 studies ») et un point ou deux-points final.
    // Le nom est coupe a 120 caracteres : MESURE du pire temps de la regle (suite de 110 espaces entre
    // le mot et une fin qui ne se lit pas), 69 ms, contre 1 ms pour un nom ordinaire.
    // Un nom qui continue apres (« Group therapy », « Group IV fluid therapy », « Topic one-year
    // outcomes », « Other studies of PTSD ») reste un nom.
    // LIMITE DITE : un fourre-tout ecrit autrement (autre langue, autre tournure, comme « Studies not
    // grouped ») reste accepte comme nom ; la liste est fermee, pour ne jamais refuser un vrai nom.
    // P24, TOUR 3 (2026-10-20, verification du tour 2) : LE COMMENTAIRE PROMETTAIT PLUS QUE LA REGLE.
    // CE QUI ETAIT FAUX : les mots « sans categorie » et « inconnu », annonces au tour 1, manquaient a
    // FT_MOT, et les dizaines francaises n'admettaient « et un » qu'avec traits d'union. MESURE (chaine
    // reelle) : « Sans catégorie », « Inconnu », « Inconnus », « Groupe vingt et un », « Thème trente
    // et un » donnaient une fusion dite faite avec ce seul theme. FT_MOT porte desormais « inconnu »
    // (et ses accords) et « sans categorie », et les dizaines « et un » s'ecrivent avec ou sans traits
    // d'union ; un nom qui continue (« Inconnu au départ : facteurs de risque ») reste un nom.
    const FT_MOT = /(?:cluster|theme|th\u00e8me|topic|group|groupe|category|cat\u00e9gorie|categorie|other|autre|misc|miscellaneous|divers|unclustered|uncategori[sz]ed|unclassified|unlabell?ed|unknown|general|g\u00e9n\u00e9ral|none|n\/a|n\.a\.?|non class\u00e9e?|inconnue?|sans\s+cat[e\u00e9]gorie)s?/;
    const FT_RANG = /(?:first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|premi\u00e8re|premier|deuxi\u00e8me|seconde|troisi\u00e8me|quatri\u00e8me|cinqui\u00e8me|sixi\u00e8me|septi\u00e8me|huiti\u00e8me|neuvi\u00e8me|dixi\u00e8me|\d+(?:st|nd|rd|th|er|re|e|\u00e8me|eme))/;
    const FT_GENERIQUE = /(?:stud(?:y|ies)|articles?|papers?|records?|reports?|topics?|themes?|items?|labels?|[e\u00e9]tudes?|th[e\u00e8]mes?|sujets?|r[e\u00e9]f[e\u00e9]rences?)/;
    const FT_NUMERO = new RegExp('(?:\\d+\\s*(?:[\\/\\-\\u2013\\u2014]|of|sur|on)\\s*\\d+' + '|(?:n\\s*[\\u00b0\\u00ba]|no\\.?|nr\\.?|num(?:ber|\\.)?|num[e\\u00e9]ro)\\s*\\d+' + '|(?:twenty|thirty|forty|fifty)(?:[\\s\\-](?:one|two|three|four|five|six|seven|eight|nine))?' + '|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen' + '|seventeen|eighteen|nineteen' + '|(?:vingt|trente|quarante|cinquante)(?:(?:-et-|\\s+et\\s+)une?|[\\s\\-](?:deux|trois|quatre|cinq|six|sept|huit|neuf))?' + '|dix(?:[\\s\\-](?:sept|huit|neuf))?|une?|deux|trois|quatre|cinq|six|sept|huit|neuf|onze|douze|treize' + '|quatorze|quinze|seize' + '|(?=[ivx])x{0,3}(?:ix|iv|v?i{0,3})|\\d+[a-z]?|[a-z])');
    const FT_EFFECTIF = new RegExp('(?:[(\\[]\\s*(?:n\\s*=\\s*)?\\d+\\s*(?:' + FT_GENERIQUE.source + ')?\\s*[)\\]]' + '|(?:[,:;\\-\\u2013\\u2014]\\s*)?(?:n\\s*=\\s*\\d+|\\d+\\s+' + FT_GENERIQUE.source + '))');
    const FOURRE_TOUT = new RegExp('^(?:' + FT_RANG.source + '\\s+)?' + FT_MOT.source + '(?:\\s*(?:[\\/&,+]|\\s(?:and|or|et|ou)\\s)\\s*' + FT_MOT.source + ')?' + '(?:\\s+' + FT_GENERIQUE.source + ')?' + '\\s*(?:[#:._\\/(\\-\\u2013\\u2014]\\s*)?(?:' + FT_NUMERO.source + ')?\\s*\\)?\\s*' + '(?:' + FT_EFFECTIF.source + ')?\\s*[.:]?$', 'i');
    for (const t of themes) {
      // P23 (2026-10-20) : SEULE UNE CHAINE NOMME UN THEME. String() faisait d'un label objet
      // « [object Object] » et d'un booleen « true », des noms de plus de deux lettres : la fusion etait
      // dite faite avec un theme vide de sens. Tout autre type ne rattache rien.
      if (!t || typeof t.label !== 'string') continue;
      const nom = t.label.trim().substring(0, 120);
      if ((nom.match(LETTRE) || []).length < 2 || FOURRE_TOUT.test(nom)) continue;
      for (const m of (t && Array.isArray(t.members)) ? t.members : []) {
        // Un indice, ou par tolerance le texte exact d'une etiquette.
        let i = null;
        if (typeof m === 'number') i = m;
        else if (typeof m === 'string' && /^\s*\d+\s*$/.test(m)) i = Number(m);
        else if (typeof m === 'string' && parTexte.has(m.trim())) i = parTexte.get(m.trim());
        if (i === null || !Number.isInteger(i) || i < 0 || i >= labels.length) continue;
        // Une etiquette citee par deux themes reste dans le premier.
        if (!nouvelle.has(labels[i])) nouvelle.set(labels[i], nom);
      }
    }
  }
}

const rattachees = nouvelle.size;
let themesApres = labels.length;
if (statut === null) {
  const apres = new Set(labels.map((l) => (nouvelle.has(l) ? nouvelle.get(l) : l)));
  if (rattachees === 0) statut = 'echec_vide';
  else if (apres.size >= labels.length) statut = 'sans_effet';
  else if (rattachees < labels.length) { statut = 'partielle'; themesApres = apres.size; }
  else { statut = 'faite'; themesApres = apres.size; }
}
const applique = statut === 'faite' || statut === 'partielle';
const _fusion = { statut: statut, etiquettes_avant: labels.length, themes_apres: themesApres,
  themes_vises: tc, rattachees: rattachees,
  budget_reponse: prevData._num_predict == null ? null : prevData._num_predict,
  contexte: prevData._num_ctx == null ? null : prevData._num_ctx,
  fin_de_reponse: ollamaResp.done_reason || null };

// Appliquer et renumeroter proprement
const labelToId = new Map();
const results = articles.map(a => {
  let label = a.cluster_label || 'Unclustered';
  if (applique && nouvelle.has(label)) label = nouvelle.get(label);
  if (!labelToId.has(label)) labelToId.set(label, labelToId.size);
  return { json: { ...a, cluster_label: label, cluster: labelToId.get(label), _fusion_themes: _fusion } };
});

console.log('Fusion des etiquettes : ' + statut + ' (' + labels.length + ' etiquettes des lots, '
  + rattachees + ' rattachees, ' + themesApres + ' themes, ' + tc + ' vises'
  + (ollamaResp.done_reason ? ', fin de reponse : ' + ollamaResp.done_reason : '') + ')');
const clusterSizes = Object.create(null);
results.forEach(r => {
  const l = r.json.cluster_label;
  clusterSizes[l] = (clusterSizes[l] || 0) + 1;
});
console.log('Clusters finaux:');
Object.entries(clusterSizes).forEach(([label, count]) => {
  console.log('  [' + count + '] ' + label);
});

return results;

